function CandidateReview({candidate,view,workspace,capability,disabled,onAction,onEditQuery,onReviewFilters}:{candidate:Candidate;view:View;workspace:Schema<"WorkspaceSummary">;capability:Capability;disabled:boolean;onAction:(kind:"approve"|"diagnose"|"execute",body:Record<string,unknown>)=>Promise<void>;onEditQuery:()=>void;onReviewFilters:()=>void}){
  const searchDefaults=useContext(SearchDefaultsContext);
  const intentVariant=view.revision.draft.variants.find(value=>value.id===candidate.id);
  const approval=view.approvals.find(value=>value.revision_id===view.revision.revision_id&&value.candidate_id===candidate.id&&value.candidate_sha256===candidate.candidate_sha256);
  const deferred=[...new Set([...candidate.deferred_required_ids,...candidate.deferred_excluded_ids])];
  const [acknowledged,setAcknowledged]=useState<string[]>(approval?.acknowledged_deferred_concept_ids??[]),[split,setSplit]=useState(approval?.accept_subquestion_split??false),[unparsed,setUnparsed]=useState(approval?.acknowledge_unparsed_strategy??false),[maximum,setMaximum]=useState(Math.min(searchDefaults.max_results,capability.limits.max_discovery_records));
  const [seeds,setSeeds]=useState<{id:string;pmid:string;doi:string;purpose:"construction"|"held_out";approved:boolean}[]>([]),[preview,setPreview]=useState("");
  const accepted=deferred.every(id=>acknowledged.includes(id))&&(!candidate.requires_split_approval||split)&&(!candidate.unparsed_constraints.length||unparsed),ready=candidate.status==="ready_for_approval";
  const diagnostics=view.diagnostics.filter(value=>value.revision_id===view.revision.revision_id&&value.candidate_id===candidate.id&&value.candidate_sha256===candidate.candidate_sha256);
  const retainedIntent=view.revision.draft.concepts.filter(value=>value.retrieval_use==="rank_only"||value.retrieval_use==="screen_later");
  const seedsReady=seeds.every(seed=>seed.approved&&!!(seed.pmid.trim()||seed.doi.trim()));
  return <article aria-label={"Compiled candidate: "+candidate.label}><h3>{candidate.label}</h3><p className="meta">{words(candidate.kind)} · {words(candidate.status)}</p><label>Exact compiled PubMed query<textarea readOnly rows={6} value={candidate.query}/></label><button type="button" disabled={disabled} onClick={onEditQuery}>Edit this query</button><p className="muted">Editing uses your exact text as a manual strategy and requires review and approval again.</p><p className="meta">SORT {candidate.sort} · DATES {candidate.date_from&&candidate.date_to?`${candidate.date_from} through ${candidate.date_to}`:"unrestricted"}</p>
    {!!retainedIntent.length&&<aside aria-label="Intent retained outside this query"><h4>Intent retained outside this query</h4><ul>{retainedIntent.map(concept=><li key={concept.id}>{concept.label} · {words(concept.requirement)} · {words(concept.retrieval_use)}</li>)}</ul><p className="muted">These concepts remain recorded for human review. They do not automatically rank results, filter records or make screening decisions.</p></aside>}
    {!!candidate.differences.length&&<><h4>Differences and deferred constraints</h4><ul>{candidate.differences.map((item,index)=><li key={index}>{item}</li>)}</ul></>}{candidate.deferred_constraints.map((item,index)=><p key={index}>{item}</p>)}{candidate.issues.map((issue,index)=><p key={index} className={issue.severity==="error"?"notice error":"muted"}>{issue.message}</p>)}
    {intentVariant?.deferral_reason&&<p className="preserve">Reason for deferral: {intentVariant.deferral_reason}</p>}{intentVariant?.split_explanation&&<p className="preserve">Reason for the separate subquestion: {intentVariant.split_explanation}</p>}
    {deferred.map(id=>{const concept=view.revision.draft.concepts.find(value=>value.id===id);return <label className="check" key={id}><input type="checkbox" checked={acknowledged.includes(id)} disabled={disabled} onChange={event=>setAcknowledged(previous=>event.target.checked?[...previous,id]:previous.filter(value=>value!==id))}/>Explicitly accept deferring {concept?.label??id} · {concept?.requirement??"constraint"} · {words(concept?.retrieval_use??"unknown")}</label>;})}
    {candidate.requires_split_approval&&<label className="check"><input type="checkbox" checked={split} disabled={disabled} onChange={event=>setSplit(event.target.checked)}/>Accept this separately run subquestion; it does not establish the original joint relationship</label>}
    {!!candidate.unparsed_constraints.length&&<><p>{candidate.unparsed_constraints.join(" ")}</p><label className="check"><input type="checkbox" checked={unparsed} disabled={disabled} onChange={event=>setUnparsed(event.target.checked)}/>Acknowledge that this exact specialist strategy has not been parsed for intent, Boolean semantics or MeSH validity</label></>}
    <div className="actions"><button type="button" disabled={disabled||!ready||!accepted||!!approval} onClick={()=>onAction("approve",{acknowledged_deferred_concept_ids:acknowledged,accept_subquestion_split:split,acknowledge_unparsed_strategy:unparsed})}>Approve this candidate</button>{approval&&<span className="meta">APPROVED <Time value={approval.created_at}/></span>}</div>
    <SearchDiagnosticSummary ready={ready} receipt={diagnostics[0]?.receipt}/>
    <div className="actions"><button type="button" disabled={disabled||!ready||!capability.diagnostics_enabled||!seedsReady} onClick={()=>onAction("diagnose",{seeds:seeds.map(seed=>({...seed,pmid:seed.pmid||null,doi:seed.doi||null,approved:true})),preview_search_id:preview||null})}>Check matches</button></div>{!capability.diagnostics_enabled&&<Notice>{capability.diagnostics_reason}</Notice>}<p className="muted">Check matches sends this exact query to PubMed and records its count, translation and warnings. Counts do not establish relevance or recall.</p>
    <details><summary>Advanced match checks and optional known-paper seeds</summary><p className="muted">Check query sends this exact candidate to bounded PubMed ESearch. Its translated query, count and small identifier sample are a diagnostic, not a complete capture or a relevance/recall score.</p>{!capability.diagnostics_enabled&&<Notice>{capability.diagnostics_reason}</Notice>}
      {seeds.map((seed,index)=><div className="retained-block" key={seed.id}><div className="control-row"><label>Known PMID {index+1}<input value={seed.pmid} disabled={disabled} onChange={event=>setSeeds(previous=>previous.map(value=>value.id===seed.id?{...value,pmid:event.target.value,approved:false}:value))}/></label><label>Known DOI {index+1}<input value={seed.doi} disabled={disabled} onChange={event=>setSeeds(previous=>previous.map(value=>value.id===seed.id?{...value,doi:event.target.value,approved:false}:value))}/></label><label>Seed purpose<select value={seed.purpose} disabled={disabled} onChange={event=>setSeeds(previous=>previous.map(value=>value.id===seed.id?{...value,purpose:event.target.value as typeof seed.purpose,approved:false}:value))}><option value="construction">Informed query construction</option><option value="held_out">Researcher-designated held out</option></select></label></div><label className="check"><input type="checkbox" checked={seed.approved} disabled={disabled} onChange={event=>setSeeds(previous=>previous.map(value=>value.id===seed.id?{...value,approved:event.target.checked}:value))}/>Approve sending these explicit identifiers for this diagnostic</label><button type="button" disabled={disabled} onClick={()=>setSeeds(previous=>previous.filter(value=>value.id!==seed.id))}>Remove known paper {index+1}</button></div>)}
      <button type="button" disabled={disabled||seeds.length>=3} onClick={()=>setSeeds(previous=>previous.length>=3?previous:[...previous,{id:identifier("seed"),pmid:"",doi:"",purpose:"construction",approved:false}])}>Add a known-paper diagnostic seed</button><label>Compare membership with a saved capped preview<select value={preview} disabled={disabled} onChange={event=>setPreview(event.target.value)}><option value="">Do not check preview recovery</option>{workspace.searches.map(search=><option key={search.id} value={search.id}>{search.query.slice(0,90)} · {new Date(search.searched_at).toLocaleString()}</option>)}</select></label>
    </details>
      {diagnostics.map(value=><div className="retained-block" key={value.receipt.id}><p className="meta">DIAGNOSTIC {words(value.receipt.status)} · <Time value={value.receipt.retrieved_at}/></p><p>{value.receipt.reported_count??"Unavailable"} provider-reported matches · sample {value.receipt.sample_pmids.length}/{value.receipt.sample_limit} · {value.receipt.calls} calls</p><p className="preserve">{value.receipt.query_translation||"Provider translation unavailable"}</p>{value.receipt.messages.map((message,index)=><p className={message.severity==="error"?"notice error":"muted"} key={index}>{message.message}</p>)}<Failure message={value.receipt.error?.message??""}/>{value.receipt.status==="succeeded"&&value.receipt.reported_count===0&&<Notice>No papers matched this query. Review tagged phrases, date filters, AND groups and provider warnings before changing the scope.<div className="actions"><button type="button" disabled={disabled} onClick={onEditQuery}>Edit query</button><button type="button" disabled={disabled} onClick={onReviewFilters}>Review filters and broader options</button></div><p>Broader options require an explicit explanation and separate acceptance of each deferred restriction. No alternative query has run.</p></Notice>}<p className="meta">SAMPLE PMIDS {value.receipt.sample_pmids.join(", ")||"none"}</p>{value.receipt.seed_results.map(item=><p key={item.seed.id}>{item.seed.pmid||item.seed.doi} · {item.seed.purpose} · query membership {words(item.query_membership)} · capped-preview recovery {words(item.preview_recovery)} · {item.reason}</p>)}<details><summary>Exact diagnostic receipt</summary><pre tabIndex={0}>{JSON.stringify(value,null,2)}</pre></details></div>)}
    {!capability.execution_enabled&&<Notice>{capability.execution_reason}</Notice>}<div className="control-row"><label>Maximum preview records<input type="number" min={1} max={capability.limits.max_discovery_records} value={maximum} disabled={disabled} onChange={event=>setMaximum(Number(event.target.value))}/></label><button type="button" className="primary" disabled={disabled||!ready||!accepted||!approval||!capability.execution_enabled||!Number.isSafeInteger(maximum)||maximum<1||maximum>capability.limits.max_discovery_records} onClick={()=>onAction("execute",{approval_id:approval!.id,max_results:maximum})}>Search papers</button></div><p className="muted">Execution saves a bounded exploratory search capture. Selection for exploration and formal review inclusion remain separate.</p><div className="actions"><a href={"/api/v1/"+workspacePath(workspace.id)+"/search-plans/"+encodeURIComponent(view.revision.plan_id)+"/strategy-export?"+new URLSearchParams({revision_id:view.revision.revision_id,candidate_id:candidate.id,format:"markdown"})}>Download readable strategy</a><a href={"/api/v1/"+workspacePath(workspace.id)+"/search-plans/"+encodeURIComponent(view.revision.plan_id)+"/strategy-export?"+new URLSearchParams({revision_id:view.revision.revision_id,candidate_id:candidate.id,format:"json"})}>Download strategy JSON</a></div><p className="muted">Exports contain this exact saved candidate, its actual approval/diagnostic/execution state and design notes. Exporting does not run a search or AI call.</p>
  </article>;
}
